using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY") ?? "";
var searchEngineId = Environment.GetEnvironmentVariable("SEARCH_ENGINE_ID") ?? "";

// --- Tool implementations ---
var notebook = new Notebook();
var webSearcher = new WebSearcher(searchApiKey, searchEngineId);

// --- Build the AI chat client with tools ---
IChatClient client = new ChatClientBuilder(
        new OpenAIClient(openAiKey).GetChatClient("gpt-4o").AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(webSearcher.SearchWeb),
        AIFunctionFactory.Create(notebook.AddNote),
        AIFunctionFactory.Create(notebook.GetNotes),
    ]
};

// --- Main loop ---
Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. When given a topic, you:
            1. Search the web for relevant information (make 2-3 searches with different queries).
            2. Take notes on key findings using the note-taking tool.
            3. After gathering enough information, retrieve your notes and produce a concise summary.
            Always use the tools available to you. End with a final written summary.
            """),
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
    };

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    var response = await client.GetChatCompletionAsync(messages, chatOptions);
    Console.WriteLine("--- Summary ---");
    Console.WriteLine(response.Message.Text);
}

Console.WriteLine("Goodbye!");

// === Tool Classes ===

/// <summary>Provides web search capabilities via Google Custom Search API.</summary>
sealed class WebSearcher(string apiKey, string engineId)
{
    private static readonly HttpClient Http = new();

    [Description("Searches the web for a given query and returns a list of result titles and snippets.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");

        if (string.IsNullOrEmpty(apiKey) || string.IsNullOrEmpty(engineId))
        {
            // Return simulated results when no API key is configured
            return $"""
                Search results for "{query}":
                1. [Simulated] No SEARCH_API_KEY/SEARCH_ENGINE_ID configured. 
                   In production, this would return real Google Custom Search results.
                   Pretend you found relevant information about: {query}
                """;
        }

        var url = $"https://www.googleapis.com/customsearch/v1?key={apiKey}&cx={engineId}&q={Uri.EscapeDataString(query)}&num=5";
        var json = await Http.GetFromJsonAsync<JsonDocument>(url);
        var items = json?.RootElement.GetProperty("items").EnumerateArray()
            .Select(item => $"- {item.GetProperty("title").GetString()}: {item.GetProperty("snippet").GetString()}");

        return items is not null
            ? $"Search results for \"{query}\":\n{string.Join("\n", items)}"
            : "No results found.";
    }
}

/// <summary>Provides note-taking capabilities for the agent to store research findings.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Adds a research note. Use this to record key findings from your searches.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} note(s)");
        return _notes.Count == 0
            ? "No notes saved yet."
            : string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    public void Clear() => _notes.Clear();
}

