+/// <summary>Provides web search capabilities via Google Custom Search API.</summary>
+sealed class WebSearcher(string apiKey, string engineId)
+{
+    private static readonly HttpClient Http = new();
+
+    [Description("Searches the web for a given query and returns a list of result titles and snippets.")]
+    public async Task<string> SearchWeb([Description("The search query")] string query)
+    {
+        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");
+
+        if (string.IsNullOrEmpty(apiKey) || string.IsNullOrEmpty(engineId))
+        {
+            // Return simulated results when no API key is configured
+            return $"""
+                Search results for "{query}":
+                1. [Simulated] No SEARCH_API_KEY/SEARCH_ENGINE_ID configured. 
+                   In production, this would return real Google Custom Search results.
+                   Pretend you found relevant information about: {query}
+                """;
+        }
+
+        var url = $"https://www.googleapis.com/customsearch/v1?key={apiKey}&cx={engineId}&q={Uri.EscapeDataString(query)}&num=5";
+        var json = await Http.GetFromJsonAsync<JsonDocument>(url);
+        var items = json?.RootElement.GetProperty("items").EnumerateArray()
+            .Select(item => $"- {item.GetProperty("title").GetString()}: {item.GetProperty("snippet").GetString()}");
+
+        return items is not null
+            ? $"Search results for \"{query}\":\n{string.Join("\n", items)}"
+            : "No results found.";
+    }
